  1→import * as cdk from "aws-cdk-lib";
  2→import * as ec2 from "aws-cdk-lib/aws-ec2";
  3→import * as ecs from "aws-cdk-lib/aws-ecs";
  4→import * as ecr from "aws-cdk-lib/aws-ecr";
  5→import * as ecs_patterns from "aws-cdk-lib/aws-ecs-patterns";
  6→import * as rds from "aws-cdk-lib/aws-rds";
  7→import * as s3 from "aws-cdk-lib/aws-s3";
  8→import * as secretsmanager from "aws-cdk-lib/aws-secretsmanager";
  9→import * as route53 from "aws-cdk-lib/aws-route53";
 10→import * as acm from "aws-cdk-lib/aws-certificatemanager";
 11→import * as logs from "aws-cdk-lib/aws-logs";
 12→import * as iam from "aws-cdk-lib/aws-iam";
 13→import * as ses from "aws-cdk-lib/aws-ses";
 14→import type { Construct } from "constructs";
 15→
 16→export interface ChatbotPlatformStackProps extends cdk.StackProps {
 17→	/** Full domain for the app, e.g. "chat.example.com" */
 18→	domainName?: string;
 19→	/** Root hosted zone name, e.g. "example.com" */
 20→	hostedZoneName?: string;
 21→	/** Route 53 hosted zone ID (from your domain registrar/existing zone) */
 22→	hostedZoneId?: string;
 23→	/** Email "From" address for verification/invite emails, e.g. "noreply@example.com" */
 24→	emailFromAddress?: string;
 25→	/** GitHub repo (owner/name) for OIDC federation, e.g. "ianshan0915/chatbot-platform" */
 26→	githubRepo?: string;
 27→}
 28→
 29→export class ChatbotPlatformStack extends cdk.Stack {
 30→	constructor(scope: Construct, id: string, props: ChatbotPlatformStackProps) {
 31→		super(scope, id, props);
 32→
 33→		// ----------------------------------------------------------------
 34→		// VPC — 2 AZs, public + private subnets (NAT gateway for outbound)
 35→		// ----------------------------------------------------------------
 36→		const vpc = new ec2.Vpc(this, "Vpc", {
 37→			maxAzs: 2,
 38→			natGateways: 1, // Keep costs low; 1 NAT is fine for non-HA start
 39→			subnetConfiguration: [
 40→				{ name: "Public", subnetType: ec2.SubnetType.PUBLIC, cidrMask: 24 },
 41→				{ name: "Private", subnetType: ec2.SubnetType.PRIVATE_WITH_EGRESS, cidrMask: 24 },
 42→			],
 43→		});
 44→
 45→		// ----------------------------------------------------------------
 46→		// S3 — file & skill storage
 47→		// ----------------------------------------------------------------
 48→		const storageBucket = new s3.Bucket(this, "StorageBucket", {
 49→			bucketName: cdk.PhysicalName.GENERATE_IF_NEEDED,
 50→			encryption: s3.BucketEncryption.S3_MANAGED,
 51→			blockPublicAccess: s3.BlockPublicAccess.BLOCK_ALL,
 52→			removalPolicy: cdk.RemovalPolicy.RETAIN, // Don't delete user files on stack destroy
 53→			versioned: true,
 54→			lifecycleRules: [
 55→				{
 56→					// Clean up incomplete multipart uploads
 57→					abortIncompleteMultipartUploadAfter: cdk.Duration.days(7),
 58→				},
 59→			],
 60→		});
 61→
 62→		// ----------------------------------------------------------------
 63→		// Secrets Manager — application secrets
 64→		// ----------------------------------------------------------------
 65→		const appSecrets = new secretsmanager.Secret(this, "AppSecrets", {
 66→			secretName: "chatbot-platform/app-secrets",
 67→			description: "Chatbot Platform application secrets (JWT_SECRET auto-generated)",
 68→			generateSecretString: {
 69→				secretStringTemplate: JSON.stringify({
 70→					JWT_SECRET: "",
 71→				}),
 72→				generateStringKey: "JWT_SECRET",
 73→				excludePunctuation: true,
 74→				passwordLength: 64,
 75→			},
 76→		});
 77→
 78→		// ENCRYPTION_ROOT_KEY needs to be a 64-char hex string (32 bytes).
 79→		// Generate it as a separate secret since CDK can only auto-generate one field.
 80→		const encryptionKeySecret = new secretsmanager.Secret(this, "EncryptionKey", {
 81→			secretName: "chatbot-platform/encryption-key",
 82→			description: "AES-256 envelope encryption root key (64 hex chars)",
 83→			generateSecretString: {
 84→				excludePunctuation: true,
 85→				excludeUppercase: true, // hex chars only: 0-9 a-f
 86→				excludeCharacters: "ghijklmnopqrstuvwxyz", // restrict to hex
 87→				passwordLength: 64,
 88→			},
 89→		});
 90→
 91→		// Brave Search API key — imported from pre-created secret
 92→		const braveSearchKey = secretsmanager.Secret.fromSecretNameV2(
 93→			this, "BraveSearchKey", "chatbot-platform/brave-search-key",
 94→		);
 95→
 96→		// ----------------------------------------------------------------
 97→		// RDS PostgreSQL — free tier eligible
 98→		// ----------------------------------------------------------------
 99→		const dbCredentials = rds.Credentials.fromGeneratedSecret("chatbot", {
100→			secretName: "chatbot-platform/db-credentials",
101→		});
102→
103→		const dbSecurityGroup = new ec2.SecurityGroup(this, "DbSecurityGroup", {
104→			vpc,
105→			description: "Security group for RDS PostgreSQL",
106→			allowAllOutbound: false,
107→		});
108→
109→		const database = new rds.DatabaseInstance(this, "Database", {
110→			engine: rds.DatabaseInstanceEngine.postgres({
111→				version: rds.PostgresEngineVersion.VER_16,
112→			}),
113→			instanceType: ec2.InstanceType.of(ec2.InstanceClass.T4G, ec2.InstanceSize.MICRO),
114→			vpc,
115→			vpcSubnets: { subnetType: ec2.SubnetType.PRIVATE_WITH_EGRESS },
116→			securityGroups: [dbSecurityGroup],
117→			credentials: dbCredentials,
118→			databaseName: "chatbot_platform",
119→			allocatedStorage: 20,
120→			maxAllocatedStorage: 50,
121→			storageEncrypted: true,
122→			multiAz: false, // Single AZ for cost savings
123→			backupRetention: cdk.Duration.days(7),
124→			deletionProtection: false, // Set to true for production
125→			removalPolicy: cdk.RemovalPolicy.SNAPSHOT,
126→		});
127→
128→		// ----------------------------------------------------------------
129→		// ECR — container registry
130→		// ----------------------------------------------------------------
131→		const repository = new ecr.Repository(this, "AppRepository", {
132→			repositoryName: "chatbot-platform",
133→			removalPolicy: cdk.RemovalPolicy.RETAIN,
134→			lifecycleRules: [
135→				{
136→					description: "Keep last 10 images",
137→					maxImageCount: 10,
138→				},
139→			],
140→		});
141→
142→		// ----------------------------------------------------------------
143→		// ECS Cluster
144→		// ----------------------------------------------------------------
145→		const cluster = new ecs.Cluster(this, "Cluster", {
146→			vpc,
147→			containerInsights: true,
148→		});
149→
150→		// ----------------------------------------------------------------
151→		// Route 53 + ACM (conditional on domain config)
152→		// ----------------------------------------------------------------
153→		let hostedZone: route53.IHostedZone | undefined;
154→		let certificate: acm.ICertificate | undefined;
155→
156→		if (props.domainName && props.hostedZoneName && props.hostedZoneId) {
157→			// Use the EXISTING hosted zone from the domain registrar.
158→			// Do NOT create a new zone — that causes orphan zones and DNS mismatch
159→			// since the registrar NS records point to the original zone.
160→			hostedZone = route53.HostedZone.fromHostedZoneAttributes(this, "HostedZone", {
161→				hostedZoneId: props.hostedZoneId,
162→				zoneName: props.hostedZoneName,
163→			});
164→
165→			certificate = new acm.Certificate(this, "Certificate", {
166→				domainName: props.domainName,
167→				validation: acm.CertificateValidation.fromDns(hostedZone),
168→			});
169→		}
170→
171→		// ----------------------------------------------------------------
172→		// SES — email delivery (verification emails, invites, job results)
173→		// ----------------------------------------------------------------
174→		// SES email identity for the domain.
175→		// Using Identity.domain() instead of Identity.publicHostedZone() because we
176→		// reference an existing zone via fromHostedZoneAttributes (returns IHostedZone,
177→		// not IPublicHostedZone). DKIM DNS records must be added manually to the zone
178→		// after first deploy (check SES console for the 3 CNAME records).
179→		if (props.hostedZoneName) {
180→			new ses.EmailIdentity(this, "SesIdentity", {
181→				identity: ses.Identity.domain(props.hostedZoneName),
182→			});
183→		}
184→
185→		// IAM user for SES SMTP credentials.
186→		// After deploy: generate SMTP credentials in IAM console for this user,
187→		// then store them in Secrets Manager under chatbot-platform/smtp-credentials.
188→		const smtpUser = new iam.User(this, "SmtpUser", {
189→			userName: "chatbot-platform-smtp",
190→		});
191→		smtpUser.addToPolicy(new iam.PolicyStatement({
192→			effect: iam.Effect.ALLOW,
193→			actions: ["ses:SendRawEmail"],
194→			resources: ["*"],
195→		}));
196→
197→		const smtpSecrets = new secretsmanager.Secret(this, "SmtpSecrets", {
198→			secretName: "chatbot-platform/smtp-credentials",
199→			description: "SES SMTP credentials — update after generating in IAM console",
200→			generateSecretString: {
201→				secretStringTemplate: JSON.stringify({
202→					username: "REPLACE_WITH_SES_SMTP_USERNAME",
203→					password: "REPLACE_WITH_SES_SMTP_PASSWORD",
204→				}),
205→				generateStringKey: "_placeholder",
206→			},
207→		});
208→
209→		// ----------------------------------------------------------------
210→		// Fargate Task Definition
211→		// ----------------------------------------------------------------
212→		const taskDefinition = new ecs.FargateTaskDefinition(this, "TaskDef", {
213→			memoryLimitMiB: 4096,
214→			cpu: 2048, // 2 vCPU — needed for child pi processes
215→		});
216→
217→		// Grant S3 access to the task role
218→		storageBucket.grantReadWrite(taskDefinition.taskRole);
219→
220→		// Grant Secrets Manager read access
221→		appSecrets.grantRead(taskDefinition.taskRole);
222→		encryptionKeySecret.grantRead(taskDefinition.taskRole);
223→		braveSearchKey.grantRead(taskDefinition.taskRole);
224→
225→		// Build DATABASE_URL from RDS secret
226→		const dbSecret = database.secret!;
227→
228→		const logGroup = new logs.LogGroup(this, "AppLogGroup", {
229→			logGroupName: "/ecs/chatbot-platform",
230→			retention: logs.RetentionDays.ONE_MONTH,
231→			removalPolicy: cdk.RemovalPolicy.RETAIN, // Keep logs for debugging failed deploys
232→		});
233→
234→		const container = taskDefinition.addContainer("app", {
235→			// Initial deployment uses a placeholder; after first `docker push` to ECR,
236→			// update to: ecs.ContainerImage.fromEcrRepository(repository, "latest")
237→			image: ecs.ContainerImage.fromEcrRepository(repository, "latest"),
238→			logging: ecs.LogDrivers.awsLogs({
239→				logGroup,
240→				streamPrefix: "app",
241→			}),
242→			environment: {
243→				NODE_ENV: "production",
244→				PORT: "3001",
245→				STORAGE_BACKEND: "s3",
246→				S3_BUCKET_NAME: storageBucket.bucketName,
247→				AWS_REGION: this.region,
248→				PROCESS_POOL_MAX: "30",
249→				PROCESS_IDLE_TIMEOUT_MS: "600000",
250→				ALLOWED_ORIGINS: props.domainName ? `https://${props.domainName}` : "",
251→				// SES SMTP (region-specific endpoint)
252→				SMTP_HOST: `email-smtp.${this.region}.amazonaws.com`,
253→				SMTP_PORT: "587",
254→				SMTP_SECURE: "false",
255→				EMAIL_FROM_ADDRESS: props.emailFromAddress || (props.domainName ? `noreply@${props.hostedZoneName || props.domainName}` : ""),
256→				APP_URL: props.domainName ? `https://${props.domainName}` : "",
257→				REGISTRATION_MODE: "open",
258→			},
259→			secrets: {
260→				// Inject individual secret fields as env vars
261→				JWT_SECRET: ecs.Secret.fromSecretsManager(appSecrets, "JWT_SECRET"),
262→				ENCRYPTION_ROOT_KEY: ecs.Secret.fromSecretsManager(encryptionKeySecret),
263→				// RDS credentials — construct DATABASE_URL in the container
264→				DB_HOST: ecs.Secret.fromSecretsManager(dbSecret, "host"),
265→				DB_PORT: ecs.Secret.fromSecretsManager(dbSecret, "port"),
266→				DB_USERNAME: ecs.Secret.fromSecretsManager(dbSecret, "username"),
267→				DB_PASSWORD: ecs.Secret.fromSecretsManager(dbSecret, "password"),
268→				DB_NAME: ecs.Secret.fromSecretsManager(dbSecret, "dbname"),
269→				// SES SMTP credentials
270→				SMTP_USER: ecs.Secret.fromSecretsManager(smtpSecrets, "username"),
271→				SMTP_PASSWORD: ecs.Secret.fromSecretsManager(smtpSecrets, "password"),
272→				// Brave Search
273→				BRAVE_SEARCH_API_KEY: ecs.Secret.fromSecretsManager(braveSearchKey),
274→			},
275→			portMappings: [{ containerPort: 3001, protocol: ecs.Protocol.TCP }],
276→			healthCheck: {
277→				command: ["CMD-SHELL", "curl -f http://localhost:3001/healthz || exit 1"],
278→				interval: cdk.Duration.seconds(30),
279→				timeout: cdk.Duration.seconds(5),
280→				retries: 3,
281→				startPeriod: cdk.Duration.seconds(60),
282→			},
283→		});
284→
285→		// ----------------------------------------------------------------
286→		// Fargate Service + ALB
287→		// ----------------------------------------------------------------
288→		const fargateService = new ecs_patterns.ApplicationLoadBalancedFargateService(
289→			this,
290→			"FargateService",
291→			{
292→				cluster,
293→				taskDefinition,
294→				desiredCount: 1,
295→				publicLoadBalancer: true,
296→				assignPublicIp: false, // Task in private subnet, outbound via NAT
297→				// Domain configuration (if provided)
298→				...(hostedZone && certificate && props.domainName
299→					? {
300→							domainName: props.domainName,
301→							domainZone: hostedZone,
302→							certificate,
303→							redirectHTTP: true,
304→						}
305→					: {}),
306→				// Health check configuration
307→				healthCheckGracePeriod: cdk.Duration.seconds(120),
308→				circuitBreaker: { rollback: true }, // Auto-rollback on repeated task failures
309→			},
310→		);
311→
312→		// Configure ALB target group for WebSocket support
313→		fargateService.targetGroup.configureHealthCheck({
314→			path: "/healthz",
315→			healthyHttpCodes: "200",
316→			interval: cdk.Duration.seconds(30),
317→			timeout: cdk.Duration.seconds(5),
318→		});
319→
320→		// Enable stickiness for WebSocket connections
321→		fargateService.targetGroup.enableCookieStickiness(cdk.Duration.days(1));
322→
323→		// Speed up deployments — WS clients auto-reconnect, no need for long drain
324→		fargateService.targetGroup.setAttribute("deregistration_delay.timeout_seconds", "30");
325→
326→		// ALB idle timeout — WebSocket connections can be long-lived
327→		fargateService.loadBalancer.setAttribute("idle_timeout.timeout_seconds", "3600");
328→
329→		// Allow Fargate tasks to connect to RDS
330→		dbSecurityGroup.addIngressRule(
331→			fargateService.service.connections.securityGroups[0],
332→			ec2.Port.tcp(5432),
333→			"Allow Fargate tasks to connect to PostgreSQL",
334→		);
335→
336→		// ----------------------------------------------------------------
337→		// Outputs
338→		// ----------------------------------------------------------------
339→		new cdk.CfnOutput(this, "LoadBalancerDNS", {
340→			value: fargateService.loadBalancer.loadBalancerDnsName,
341→			description: "ALB DNS name (use this if no custom domain)",
342→		});
343→
344→		new cdk.CfnOutput(this, "EcrRepositoryUri", {
345→			value: repository.repositoryUri,
346→			description: "ECR repository URI for docker push",
347→		});
348→
349→		new cdk.CfnOutput(this, "StorageBucketName", {
350→			value: storageBucket.bucketName,
351→			description: "S3 bucket for file storage",
352→		});
353→
354→		new cdk.CfnOutput(this, "DatabaseEndpoint", {
355→			value: database.instanceEndpoint.hostname,
356→			description: "RDS PostgreSQL endpoint",
357→		});
358→
359→		new cdk.CfnOutput(this, "AppSecretsArn", {
360→			value: appSecrets.secretArn,
361→			description: "Secrets Manager ARN — update ENCRYPTION_ROOT_KEY after deploy",
362→		});
363→
364→		if (props.domainName) {
365→			new cdk.CfnOutput(this, "AppUrl", {
366→				value: `https://${props.domainName}`,
367→				description: "Application URL",
368→			});
369→		}
370→
371→		new cdk.CfnOutput(this, "SmtpUserName", {
372→			value: smtpUser.userName,
373→			description: "IAM user for SES SMTP — generate SMTP credentials in IAM console",
374→		});
375→
376→		new cdk.CfnOutput(this, "SmtpSecretsArn", {
377→			value: smtpSecrets.secretArn,
378→			description: "Secrets Manager ARN — store SES SMTP credentials here",
379→		});
380→
381→		new cdk.CfnOutput(this, "SmtpEndpoint", {
382→			value: `email-smtp.${this.region}.amazonaws.com:587`,
383→			description: "SES SMTP endpoint",
384→		});
385→
386→		// ----------------------------------------------------------------
387→		// GitHub Actions OIDC — keyless AWS auth for CI/CD
388→		// ----------------------------------------------------------------
389→		if (props.githubRepo) {
390→			const ghOidcProvider = new iam.OpenIdConnectProvider(this, "GitHubOidc", {
391→				url: "https://token.actions.githubusercontent.com",
392→				clientIds: ["sts.amazonaws.com"],
393→			});
394→
395→			const deployRole = new iam.Role(this, "GitHubActionsRole", {
396→				roleName: "chatbot-platform-github-actions",
397→				assumedBy: new iam.WebIdentityPrincipal(
398→					ghOidcProvider.openIdConnectProviderArn,
399→					{
400→						StringLike: {
401→							"token.actions.githubusercontent.com:sub": `repo:${props.githubRepo}:*`,
402→						},
403→						StringEquals: {
404→							"token.actions.githubusercontent.com:aud": "sts.amazonaws.com",
405→						},
406→					},
407→				),
408→				managedPolicies: [
409→					iam.ManagedPolicy.fromAwsManagedPolicyName("AdministratorAccess"),
410→				],
411→			});
412→
413→			new cdk.CfnOutput(this, "GitHubActionsRoleArn", {
414→				value: deployRole.roleArn,
415→				description: "IAM role ARN for GitHub Actions — set as AWS_DEPLOY_ROLE_ARN secret",
416→			});
417→		}
418→	}
419→}
