 1→import { Pool } from "pg";
 2→import type { Database } from "./types.js";
 3→
 4→let _db: Database | null = null;
 5→
 6→/** Create and return a Database singleton. Call once at startup. */
 7→export function createDatabase(connectionString?: string): Database {
 8→	if (_db) return _db;
 9→
10→	const connString = connectionString || process.env.DATABASE_URL;
11→	const pool = new Pool({
12→		connectionString: connString,
13→		max: 20,
14→		idleTimeoutMillis: 30_000,
15→		connectionTimeoutMillis: 5_000,
16→		// Enable SSL for RDS (production). The pg library ignores sslmode in the URL.
17→		// rejectUnauthorized: false is acceptable within VPC (security group restricts access).
18→		...(process.env.NODE_ENV === "production" ? { ssl: { rejectUnauthorized: false } } : {}),
19→	});
20→
21→	pool.on("error", (err) => {
22→		console.error("[db] Unexpected pool error:", err.message);
23→	});
24→
25→	const db: Database = {
26→		pool,
27→		query: (text, params) => pool.query(text, params),
28→		getClient: () => pool.connect(),
29→	};
30→
31→	_db = db;
32→	return db;
33→}
34→
35→/** Get the existing Database singleton. Throws if not yet created. */
36→export function getDatabase(): Database {
37→	if (!_db) {
38→		throw new Error("Database not initialized. Call createDatabase() first.");
39→	}
40→	return _db;
41→}
