  1→/**
  2→ * Team member management routes (admin-only).
  3→ *
  4→ * CRUD for users within the admin's team.
  5→ * Supports both adding existing users (by email) and creating new users.
  6→ */
  7→
  8→import { Router } from "express";
  9→import bcrypt from "bcryptjs";
 10→import { getDatabase } from "../db/index.js";
 11→import { requireAuth } from "../auth/middleware.js";
 12→import { requireRole } from "../auth/permissions.js";
 13→import { validatePassword, ValidationError } from "../auth/local-auth.js";
 14→import { asyncRoute } from "../utils/async-handler.js";
 15→
 16→const SALT_ROUNDS = 12;
 17→const VALID_ROLES = new Set(["admin", "member"]);
 18→
 19→export function createTeamMembersRouter(): Router {
 20→	const router = Router();
 21→
 22→	// All routes require admin role
 23→	router.use(requireAuth, requireRole("admin"));
 24→
 25→	// -----------------------------------------------------------------------
 26→	// GET / — List team members
 27→	// -----------------------------------------------------------------------
 28→	router.get("/", asyncRoute(async (req, res) => {
 29→		const db = getDatabase();
 30→		const result = await db.query(
 31→			`SELECT id, email, display_name, role, created_at, last_login
 32→			 FROM users WHERE team_id = $1 ORDER BY created_at`,
 33→			[req.user!.teamId],
 34→		);
 35→
 36→		res.json({ success: true, data: { members: result.rows } });
 37→	}));
 38→
 39→	// -----------------------------------------------------------------------
 40→	// GET /search?email=... — Search for existing users (for adding to team)
 41→	// -----------------------------------------------------------------------
 42→	router.get("/search", asyncRoute(async (req, res) => {
 43→		const email = req.query.email as string;
 44→		if (!email || typeof email !== "string" || email.length < 2) {
 45→			res.status(400).json({ success: false, error: "email query parameter required (min 2 chars)" });
 46→			return;
 47→		}
 48→
 49→		const db = getDatabase();
 50→		const result = await db.query(
 51→			`SELECT id, email, display_name, team_id FROM users
 52→			 WHERE email ILIKE $1 AND team_id != $2
 53→			 ORDER BY email LIMIT 10`,
 54→			[`%${email}%`, req.user!.teamId],
 55→		);
 56→
 57→		res.json({ success: true, data: { users: result.rows } });
 58→	}));
 59→
 60→	// -----------------------------------------------------------------------
 61→	// POST / — Add a member to the team
 62→	//
 63→	// Two modes:
 64→	// 1. { userId } — Move an existing user into admin's team
 65→	// 2. { email, password, displayName?, role? } — Create a new user in admin's team
 66→	// -----------------------------------------------------------------------
 67→	router.post("/", asyncRoute(async (req, res) => {
 68→		const db = getDatabase();
 69→		const { userId, email, password, displayName, role } = req.body;
 70→
 71→		const memberRole = role || "member";
 72→		if (!VALID_ROLES.has(memberRole)) {
 73→			res.status(400).json({ success: false, error: "role must be 'admin' or 'member'" });
 74→			return;
 75→		}
 76→
 77→		// Mode 1: Add existing user by ID
 78→		if (userId) {
 79→			const { rows: target } = await db.query(
 80→				"SELECT id, email, team_id FROM users WHERE id = $1",
 81→				[userId],
 82→			);
 83→			if (target.length === 0) {
 84→				res.status(404).json({ success: false, error: "User not found" });
 85→				return;
 86→			}
 87→			if (target[0].team_id === req.user!.teamId) {
 88→				res.status(409).json({ success: false, error: "User is already in your team" });
 89→				return;
 90→			}
 91→
 92→			await db.query(
 93→				"UPDATE users SET team_id = $1, role = $2 WHERE id = $3",
 94→				[req.user!.teamId, memberRole, userId],
 95→			);
 96→
 97→			const { rows } = await db.query(
 98→				"SELECT id, email, display_name, role, created_at, last_login FROM users WHERE id = $1",
 99→				[userId],
100→			);
101→
102→			res.status(200).json({ success: true, data: { member: rows[0] } });
103→			return;
104→		}
105→
106→		// Mode 2: Create new user
107→		if (!email || typeof email !== "string") {
108→			res.status(400).json({ success: false, error: "email is required" });
109→			return;
110→		}
111→		if (!password || typeof password !== "string") {
112→			res.status(400).json({ success: false, error: "password is required" });
113→			return;
114→		}
115→
116→		try {
117→			validatePassword(password);
118→		} catch (err) {
119→			if (err instanceof ValidationError) {
120→				res.status(400).json({ success: false, error: err.message });
121→				return;
122→			}
123→			throw err;
124→		}
125→
126→		// Check for existing user with this email
127→		const { rows: existing } = await db.query(
128→			"SELECT id FROM users WHERE email = $1",
129→			[email],
130→		);
131→		if (existing.length > 0) {
132→			res.status(409).json({ success: false, error: "A user with this email already exists. Use the search to add them instead." });
133→			return;
134→		}
135→
136→		const passwordHash = await bcrypt.hash(password, SALT_ROUNDS);
137→
138→		const { rows } = await db.query(
139→			`INSERT INTO users (team_id, email, password_hash, display_name, role, email_verified)
140→			 VALUES ($1, $2, $3, $4, $5, TRUE)
141→			 RETURNING id, email, display_name, role, created_at`,
142→			[req.user!.teamId, email, passwordHash, displayName || null, memberRole],
143→		);
144→
145→		res.status(201).json({ success: true, data: { member: rows[0] } });
146→	}));
147→
148→	// -----------------------------------------------------------------------
149→	// PATCH /:userId — Change a member's role
150→	// -----------------------------------------------------------------------
151→	router.patch("/:userId", asyncRoute(async (req, res) => {
152→		const { userId } = req.params;
153→		const { role } = req.body;
154→
155→		if (!role || !VALID_ROLES.has(role)) {
156→			res.status(400).json({ success: false, error: "role must be 'admin' or 'member'" });
157→			return;
158→		}
159→
160→		const db = getDatabase();
161→
162→		// Verify target is in the same team
163→		const { rows: target } = await db.query(
164→			"SELECT id, role FROM users WHERE id = $1 AND team_id = $2",
165→			[userId, req.user!.teamId],
166→		);
167→		if (target.length === 0) {
168→			res.status(404).json({ success: false, error: "User not found in your team" });
169→			return;
170→		}
171→
172→		// Guard: cannot demote the last admin
173→		if (target[0].role === "admin" && role !== "admin") {
174→			const { rows: admins } = await db.query(
175→				"SELECT id FROM users WHERE team_id = $1 AND role = 'admin'",
176→				[req.user!.teamId],
177→			);
178→			if (admins.length <= 1) {
179→				res.status(400).json({ success: false, error: "Cannot demote the last admin" });
180→				return;
181→			}
182→		}
183→
184→		const updateResult = await db.query(
185→			"UPDATE users SET role = $1 WHERE id = $2 AND team_id = $3",
186→			[role, userId, req.user!.teamId],
187→		);
188→
189→		if (updateResult.rowCount === 0) {
190→			res.status(404).json({ success: false, error: "User not found in your team" });
191→			return;
192→		}
193→
194→		res.json({ success: true });
195→	}));
196→
197→	// -----------------------------------------------------------------------
198→	// DELETE /:userId — Remove a member from the team
199→	// -----------------------------------------------------------------------
200→	router.delete("/:userId", asyncRoute(async (req, res) => {
201→		const { userId } = req.params;
202→
203→		// Cannot remove self
204→		if (userId === req.user!.userId) {
205→			res.status(400).json({ success: false, error: "Cannot remove yourself" });
206→			return;
207→		}
208→
209→		const db = getDatabase();
210→
211→		// Verify target is in the same team
212→		const result = await db.query(
213→			"DELETE FROM users WHERE id = $1 AND team_id = $2",
214→			[userId, req.user!.teamId],
215→		);
216→
217→		if (result.rowCount === 0) {
218→			res.status(404).json({ success: false, error: "User not found in your team" });
219→			return;
220→		}
221→
222→		res.json({ success: true });
223→	}));
224→
225→	return router;
226→}
