  1→import { Router } from "express";
  2→import type { LoginRequest, RegisterRequest } from "../auth/types.js";
  3→import {
  4→	registerUser,
  5→	loginUser,
  6→	verifyEmail,
  7→	resendVerification,
  8→	ConflictError,
  9→	AuthError,
 10→	ValidationError,
 11→	LockoutError,
 12→	UnverifiedError,
 13→} from "../auth/local-auth.js";
 14→import { requireAuth } from "../auth/middleware.js";
 15→import { createSseTicket } from "../auth/sse-tickets.js";
 16→import { signupRateLimit } from "../middleware/rate-limit.js";
 17→import { verifyTurnstileToken } from "../services/turnstile.js";
 18→import { getDatabase } from "../db/index.js";
 19→
 20→const router = Router();
 21→
 22→// POST /api/auth/register
 23→router.post("/register", signupRateLimit, async (req, res) => {
 24→	const { email, password, displayName, teamName, inviteToken, turnstileToken } =
 25→		req.body as RegisterRequest;
 26→
 27→	if (!email || !password) {
 28→		res.status(400).json({ success: false, error: "Email and password are required" });
 29→		return;
 30→	}
 31→
 32→	try {
 33→		// Verify Turnstile token first (fail fast)
 34→		const turnstileValid = await verifyTurnstileToken(turnstileToken || "", req.ip);
 35→		if (!turnstileValid) {
 36→			res.status(400).json({ success: false, error: "CAPTCHA verification failed. Please try again." });
 37→			return;
 38→		}
 39→
 40→		// Check invite-only mode
 41→		const registrationMode = process.env.REGISTRATION_MODE || "open";
 42→		if (registrationMode === "invite" && !inviteToken) {
 43→			res.status(403).json({ success: false, error: "Registration is by invitation only" });
 44→			return;
 45→		}
 46→
 47→		const db = getDatabase();
 48→		const data = await registerUser(db, email, password, displayName, teamName, inviteToken);
 49→		res.status(201).json({ success: true, data });
 50→	} catch (err) {
 51→		if (err instanceof ValidationError) {
 52→			res.status(400).json({ success: false, error: err.message });
 53→			return;
 54→		}
 55→		if (err instanceof ConflictError) {
 56→			// Return same 201 response to prevent email enumeration
 57→			res.status(201).json({
 58→				success: true,
 59→				data: {
 60→					message: "Account created. Please check your email to verify your address.",
 61→					requiresVerification: true,
 62→				},
 63→			});
 64→			console.warn(`[auth] Registration attempt with existing email: ${email}`);
 65→			return;
 66→		}
 67→		throw err;
 68→	}
 69→});
 70→
 71→// GET /api/auth/verify?token=...
 72→router.get("/verify", async (req, res) => {
 73→	const token = req.query.token as string;
 74→	if (!token) {
 75→		res.status(400).json({ success: false, error: "Verification token required" });
 76→		return;
 77→	}
 78→
 79→	try {
 80→		const db = getDatabase();
 81→		await verifyEmail(db, token);
 82→		const appUrl = process.env.APP_URL || "http://localhost:3001";
 83→		res.redirect(`${appUrl}/?verified=true`);
 84→	} catch (err) {
 85→		if (err instanceof ValidationError) {
 86→			res.status(400).json({ success: false, error: err.message });
 87→			return;
 88→		}
 89→		throw err;
 90→	}
 91→});
 92→
 93→// POST /api/auth/resend-verification
 94→router.post("/resend-verification", signupRateLimit, async (req, res) => {
 95→	const { email } = req.body;
 96→	if (!email) {
 97→		res.status(400).json({ success: false, error: "Email is required" });
 98→		return;
 99→	}
100→
101→	try {
102→		const db = getDatabase();
103→		await resendVerification(db, email);
104→	} catch {
105→		// Swallow errors to prevent enumeration
106→	}
107→
108→	// Always return success
109→	res.json({ success: true, message: "If an account exists with that email, a verification link has been sent." });
110→});
111→
112→// GET /api/auth/registration-config — public endpoint for frontend to know what to render
113→router.get("/registration-config", (_req, res) => {
114→	res.json({
115→		mode: process.env.REGISTRATION_MODE || "open",
116→		turnstileSiteKey: process.env.TURNSTILE_SITE_KEY || null,
117→	});
118→});
119→
120→// POST /api/auth/login
121→router.post("/login", async (req, res) => {
122→	const { email, password } = req.body as LoginRequest;
123→
124→	if (!email || !password) {
125→		res.status(400).json({ success: false, error: "Email and password are required" });
126→		return;
127→	}
128→
129→	try {
130→		const db = getDatabase();
131→		const data = await loginUser(db, email, password);
132→		res.json({ success: true, data });
133→	} catch (err) {
134→		if (err instanceof LockoutError) {
135→			res.status(429).json({ success: false, error: err.message });
136→			return;
137→		}
138→		if (err instanceof UnverifiedError) {
139→			res.status(403).json({ success: false, error: err.message, code: "EMAIL_NOT_VERIFIED" });
140→			return;
141→		}
142→		if (err instanceof AuthError) {
143→			res.status(401).json({ success: false, error: err.message });
144→			return;
145→		}
146→		throw err;
147→	}
148→});
149→
150→// GET /api/auth/me
151→router.get("/me", requireAuth, (req, res) => {
152→	res.json({ success: true, data: { user: req.user } });
153→});
154→
155→// POST /api/auth/sse-ticket — Issue a short-lived, single-use ticket for SSE auth
156→router.post("/sse-ticket", requireAuth, (req, res) => {
157→	const ticket = createSseTicket(req.user!);
158→	res.json({ success: true, data: { ticket } });
159→});
160→
161→export default router;
