 12→// ---------- helpers ----------
 13→
 14→interface SettingsRow {
 15→	user_settings: Record<string, unknown>;
 16→	team_settings: Record<string, unknown>;
 17→	team_name: string;
 18→	role: string;
 19→}
 20→
 21→async function fetchSettings(userId: string, teamId: string): Promise<SettingsRow> {
 22→	const db = getDatabase();
 23→	const { rows } = await db.query(
 24→		`SELECT u.settings AS user_settings,
 25→		        t.settings AS team_settings,
 26→		        t.name     AS team_name,
 27→		        u.role
 28→		   FROM users u
 29→		   JOIN teams t ON u.team_id = t.id
 30→		  WHERE u.id = $1 AND u.team_id = $2`,
 31→		[userId, teamId],
 32→	);
 33→	return rows[0] as SettingsRow;
 34→}
 35→
 36→function settingsPayload(row: SettingsRow) {
 37→	return {
 38→		userSettings: row.user_settings ?? {},
 39→		teamSettings: row.team_settings ?? {},
 40→		teamName: row.team_name,
 41→		role: row.role,
 42→	};
 43→}
 44→
 45→// ---------- GET / ----------
 46→
 47→router.get("/", async (req: Request, res: Response) => {
 48→	try {
 49→		const { userId, teamId } = req.user!;
 50→		const row = await fetchSettings(userId, teamId);
 51→		if (!row) {
 52→			res.status(404).json({ success: false, error: "User not found" });
 53→			return;
 54→		}
 55→		res.json({ success: true, data: settingsPayload(row) });
 56→	} catch (err) {
 57→		console.error("[settings] GET / error:", err);
 58→		res.status(500).json({ success: false, error: "Failed to fetch settings" });
 59→	}
 60→});
 61→
 62→// ---------- PATCH / ----------
 63→
 64→router.patch("/", async (req: Request, res: Response) => {
 65→	try {
 66→		const { userId, teamId } = req.user!;
 67→		const { settings } = req.body as { settings?: Record<string, unknown> };
 68→
 69→		if (!settings || typeof settings !== "object") {
 70→			res.status(400).json({ success: false, error: "Invalid settings payload" });
 71→			return;
 72→		}
 73→
 74→		const db = getDatabase();
 75→		await db.query(
 76→			`UPDATE users SET settings = settings || $1::jsonb WHERE id = $2`,
 77→			[JSON.stringify(settings), userId],
 78→		);
 79→
 80→		const row = await fetchSettings(userId, teamId);
 81→		res.json({ success: true, data: settingsPayload(row) });
 82→	} catch (err) {
 83→		console.error("[settings] PATCH / error:", err);
 84→		res.status(500).json({ success: false, error: "Failed to update user settings" });
 85→	}
 86→});
 87→
 88→// ---------- PATCH /team ----------
 89→
 90→router.patch("/team", requireRole("admin"), async (req: Request, res: Response) => {
 91→	try {
 92→		const { userId, teamId } = req.user!;
 93→		const { settings, name } = req.body as {
 94→			settings?: Record<string, unknown>;
 95→			name?: string;
 96→		};
 97→
 98→		if (!settings && !name) {
 99→			res.status(400).json({ success: false, error: "Nothing to update" });
100→			return;
101→		}
102→
103→		const db = getDatabase();
104→
105→		if (settings && typeof settings === "object") {
106→			await db.query(
107→				`UPDATE teams SET settings = settings || $1::jsonb WHERE id = $2`,
108→				[JSON.stringify(settings), teamId],
109→			);
110→		}
111→
112→		if (name && typeof name === "string") {
113→			await db.query(
114→				`UPDATE teams SET name = $1 WHERE id = $2`,
115→				[name, teamId],
116→			);
117→		}
118→
119→		const row = await fetchSettings(userId, teamId);
120→		res.json({ success: true, data: settingsPayload(row) });
121→	} catch (err) {
122→		console.error("[settings] PATCH /team error:", err);
123→		res.status(500).json({ success: false, error: "Failed to update team settings" });
124→	}
125→});
