  1→/**
  2→ * Invite token management routes.
  3→ *
  4→ * Admins can create, list, and revoke invite tokens for their team.
  5→ * Public validate endpoint lets the frontend check if an invite is valid.
  6→ */
  7→
  8→import { Router } from "express";
  9→import crypto from "node:crypto";
 10→import { getDatabase } from "../db/index.js";
 11→import { requireAuth } from "../auth/middleware.js";
 12→import { requireRole } from "../auth/permissions.js";
 13→import { sendInviteEmail } from "../services/email.js";
 14→import { asyncRoute } from "../utils/async-handler.js";
 15→
 16→export function createInvitesRouter(): Router {
 17→	const router = Router();
 18→
 19→	// GET /api/invites/validate?token=... — public, check if token is valid
 20→	router.get("/validate", asyncRoute(async (req, res) => {
 21→		const token = req.query.token as string;
 22→		if (!token) {
 23→			res.status(400).json({ success: false, error: "Token required" });
 24→			return;
 25→		}
 26→
 27→		const db = getDatabase();
 28→		const { rows } = await db.query<{ team_name: string; email: string | null }>(
 29→			`SELECT t.name as team_name, i.email
 30→			 FROM invite_tokens i
 31→			 JOIN teams t ON t.id = i.team_id
 32→			 WHERE i.token = $1 AND i.revoked_at IS NULL AND i.expires_at > NOW()
 33→			   AND i.use_count < i.max_uses`,
 34→			[token],
 35→		);
 36→
 37→		if (rows.length === 0) {
 38→			res.json({ success: true, data: { valid: false } });
 39→			return;
 40→		}
 41→
 42→		res.json({
 43→			success: true,
 44→			data: {
 45→				valid: true,
 46→				teamName: rows[0].team_name,
 47→				restrictedEmail: rows[0].email || null,
 48→			},
 49→		});
 50→	}));
 51→
 52→	// All remaining routes require admin auth
 53→	router.use(requireAuth, requireRole("admin"));
 54→
 55→	// GET /api/invites — list active invite tokens for admin's team
 56→	router.get("/", asyncRoute(async (req, res) => {
 57→		const db = getDatabase();
 58→		const { rows } = await db.query(
 59→			`SELECT i.id, i.token, i.label, i.email, i.max_uses, i.use_count,
 60→			        i.expires_at, i.created_at, u.email as created_by_email
 61→			 FROM invite_tokens i
 62→			 JOIN users u ON u.id = i.created_by
 63→			 WHERE i.team_id = $1 AND i.revoked_at IS NULL
 64→			 ORDER BY i.created_at DESC`,
 65→			[req.user!.teamId],
 66→		);
 67→
 68→		res.json({ success: true, data: { invites: rows } });
 69→	}));
 70→
 71→	// POST /api/invites — create a new invite token
 72→	router.post("/", asyncRoute(async (req, res) => {
 73→		const { email, label, maxUses } = req.body;
 74→		const db = getDatabase();
 75→
 76→		const token = crypto.randomBytes(24).toString("hex");
 77→		const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days
 78→
 79→		const { rows } = await db.query(
 80→			`INSERT INTO invite_tokens (team_id, created_by, token, label, email, max_uses, expires_at)
 81→			 VALUES ($1, $2, $3, $4, $5, $6, $7)
 82→			 RETURNING id, token, label, email, max_uses, use_count, expires_at, created_at`,
 83→			[
 84→				req.user!.teamId,
 85→				req.user!.userId,
 86→				token,
 87→				label || null,
 88→				email || null,
 89→				maxUses || 1,
 90→				expiresAt,
 91→			],
 92→		);
 93→
 94→		const invite = rows[0];
 95→		const appUrl = process.env.APP_URL || "http://localhost:3001";
 96→		const inviteUrl = `${appUrl}/?invite=${token}`;
 97→
 98→		// Send invite email if email was provided
 99→		if (email) {
100→			try {
101→				const teamResult = await db.query<{ name: string }>(
102→					"SELECT name FROM teams WHERE id = $1",
103→					[req.user!.teamId],
104→				);
105→				const teamName = teamResult.rows[0]?.name || "the team";
106→				const inviterName = req.user!.displayName || req.user!.email;
107→				await sendInviteEmail(email, inviteUrl, teamName, inviterName);
108→			} catch (err) {
109→				console.error("[invites] Failed to send invite email:", err);
110→				// Don't fail the invite creation
111→			}
112→		}
113→
114→		res.status(201).json({
115→			success: true,
116→			data: { invite: { ...invite, url: inviteUrl } },
117→		});
118→	}));
119→
120→	// DELETE /api/invites/:id — revoke an invite
121→	router.delete("/:id", asyncRoute(async (req, res) => {
122→		const { id } = req.params;
123→		const db = getDatabase();
124→
125→		const result = await db.query(
126→			"UPDATE invite_tokens SET revoked_at = NOW() WHERE id = $1 AND team_id = $2 AND revoked_at IS NULL",
127→			[id, req.user!.teamId],
128→		);
129→
130→		if (result.rowCount === 0) {
131→			res.status(404).json({ success: false, error: "Invite not found" });
132→			return;
133→		}
134→
135→		res.json({ success: true });
136→	}));
137→
138→	return router;
139→}
