 15→/** Models to try for auto-grouping, in preference order. */
 16→const ORGANIZE_MODEL_CANDIDATES: { provider: string; envVar: string; modelId: string }[] = [
 17→	{ provider: "anthropic", envVar: "ANTHROPIC_API_KEY", modelId: "claude-3-5-haiku-20241022" },
