 24→export function createProjectsRouter(agentExecutor: AgentExecutor): Router {
 25→	const router = Router();
 26→	router.use(requireAuth);
 27→
 28→	// -----------------------------------------------------------------------
 29→	// GET / — List user's projects ordered by sort_order
 30→	// -----------------------------------------------------------------------
 31→	router.get("/", asyncRoute(async (req, res) => {
 32→		const db = getDatabase();
 33→		const result = await db.query<ProjectRow>(
 34→			`SELECT * FROM projects WHERE user_id = $1 ORDER BY sort_order, created_at`,
 35→			[req.user!.userId],
 36→		);
 37→		res.json({ success: true, data: { projects: result.rows } });
 38→	}));
 39→
 40→	// -----------------------------------------------------------------------
 41→	// POST / — Create a new project
 42→	// -----------------------------------------------------------------------
 43→	router.post("/", asyncRoute(async (req, res) => {
 44→		const db = getDatabase();
 45→		const { name, icon } = req.body;
 46→
 47→		if (!name || typeof name !== "string" || !name.trim()) {
 48→			res.status(400).json({ success: false, error: "name is required" });
 49→			return;
 50→		}
 51→
 52→		// Default sort_order: after existing projects
 53→		const maxResult = await db.query<{ max_order: number | null }>(
 54→			`SELECT MAX(sort_order) AS max_order FROM projects WHERE user_id = $1`,
 55→			[req.user!.userId],
 56→		);
 57→		const sortOrder = (maxResult.rows[0].max_order ?? -1) + 1;
 58→
 59→		const result = await db.query<ProjectRow>(
 60→			`INSERT INTO projects (user_id, name, icon, sort_order)
 61→			 VALUES ($1, $2, $3, $4)
 62→			 RETURNING *`,
 63→			[req.user!.userId, name.trim(), icon ?? null, sortOrder],
 64→		);
 65→
 66→		res.status(201).json({ success: true, data: { project: result.rows[0] } });
 67→	}));
 68→
 69→	// -----------------------------------------------------------------------
 70→	// PATCH /:id — Update project name/icon/sort_order
 71→	// -----------------------------------------------------------------------
 72→	router.patch("/:id", asyncRoute(async (req, res) => {
 73→		const db = getDatabase();
 74→		const { id } = req.params;
 75→
 76→		// Ownership check
 77→		const existing = await db.query<ProjectRow>(
 78→			`SELECT * FROM projects WHERE id = $1 AND user_id = $2`,
 79→			[id, req.user!.userId],
 80→		);
 81→		if (existing.rows.length === 0) {
 82→			res.status(404).json({ success: false, error: "Project not found" });
 83→			return;
 84→		}
 85→
 86→		const { name, icon, sort_order } = req.body;
 87→		const result = await db.query<ProjectRow>(
 88→			`UPDATE projects
 89→			 SET name = COALESCE($1, name),
 90→			     icon = COALESCE($2, icon),
 91→			     sort_order = COALESCE($3, sort_order)
 92→			 WHERE id = $4 AND user_id = $5
 93→			 RETURNING *`,
 94→			[name ?? null, icon ?? null, sort_order ?? null, id, req.user!.userId],
 95→		);
 96→
 97→		res.json({ success: true, data: { project: result.rows[0] } });
 98→	}));
 99→
100→	// -----------------------------------------------------------------------
101→	// DELETE /:id — Delete project (sessions get project_id = NULL via FK)
102→	// -----------------------------------------------------------------------
103→	router.delete("/:id", asyncRoute(async (req, res) => {
104→		const db = getDatabase();
105→		const { id } = req.params;
106→
107→		const result = await db.query(
108→			`DELETE FROM projects WHERE id = $1 AND user_id = $2`,
109→			[id, req.user!.userId],
110→		);
111→
112→		if (result.rowCount === 0) {
113→			res.status(404).json({ success: false, error: "Project not found" });
114→			return;
115→		}
116→
117→		res.json({ success: true });
118→	}));
119→
120→	// -----------------------------------------------------------------------
121→	// POST /organize — AI auto-grouping of ungrouped sessions
122→	// -----------------------------------------------------------------------
123→	router.post("/organize", asyncRoute(async (req, res) => {
124→		const db = getDatabase();
125→		const userId = req.user!.userId;
126→
127→		// 1. Fetch ungrouped sessions
128→		const sessionsResult = await db.query<Pick<SessionRow, "id" | "title" | "preview">>(
129→			`SELECT id, title, preview FROM sessions
130→			 WHERE user_id = $1 AND project_id IS NULL AND deleted_at IS NULL
131→			 ORDER BY last_modified DESC`,
132→			[userId],
133→		);
134→
135→		const ungrouped = sessionsResult.rows;
136→		if (ungrouped.length < 3) {
137→			res.status(400).json({ success: false, error: "Need at least 3 ungrouped sessions to organize" });
138→			return;
139→		}
140→
141→		// 2. Find available LLM
142→		const env = await agentExecutor.buildEnv(userId, req.user!.teamId);
143→		let apiKey: string | undefined;
144→		let model: ReturnType<typeof getModel> | undefined;
145→
146→		for (const candidate of ORGANIZE_MODEL_CANDIDATES) {
147→			const key = env[candidate.envVar];
148→			if (!key) continue;
149→			const m = getModel(candidate.provider as any, candidate.modelId);
150→			if (!m) continue;
151→			apiKey = key;
152→			model = m;
153→			break;
154→		}
155→
156→		if (!apiKey || !model) {
157→			res.status(400).json({ success: false, error: "No LLM provider configured" });
158→			return;
159→		}
160→
161→		// 3. Build prompt with session data
162→		const sessionSummaries = ungrouped.map(s =>
163→			`- ID: ${s.id} | Title: "${s.title}" | Preview: "${(s.preview || "").slice(0, 100)}"`
164→		).join("\n");
165→
166→		const context: Context = {
167→			messages: [{
168→				role: "user",
169→				content: `You are organizing chat sessions into project folders. Group these sessions by topic/theme.
170→
171→Sessions:
172→${sessionSummaries}
173→
174→Reply with ONLY valid JSON (no markdown, no explanation). Format:
175→[{"projectName": "Short name", "icon": "single emoji", "sessionIds": ["id1", "id2"]}]
176→
177→Rules:
178→- Group related sessions together (2+ sessions per group preferred)
179→- Use short, descriptive project names (2-4 words)
180→- Pick a single emoji icon that represents the group
181→- Every session must appear in exactly one group
182→- Aim for 2-5 groups total`,
183→				timestamp: Date.now(),
184→			}],
185→		};
186→
187→		try {
188→			const result = await complete(model, context, {
189→				apiKey,
190→				maxTokens: 2000,
191→			} as any);
192→
193→			const textPart = result.content?.find((c: any) => c.type === "text");
194→			const rawText = textPart && "text" in textPart ? textPart.text.trim() : "";
195→
196→			// Parse JSON (strip markdown fences if present)
197→			const jsonStr = rawText.replace(/^```(?:json)?\s*/, "").replace(/\s*```$/, "");
198→			const groups: Array<{ projectName: string; icon: string; sessionIds: string[] }> = JSON.parse(jsonStr);
199→
200→			if (!Array.isArray(groups) || groups.length === 0) {
201→				res.status(500).json({ success: false, error: "Invalid grouping response from AI" });
202→				return;
203→			}
204→
205→			// 4. Validate sessionIds — only allow IDs that are actually ungrouped
206→			const validIds = new Set(ungrouped.map(s => s.id));
207→
208→			// 5. Create projects and assign sessions in a transaction
209→			const client = await db.getClient();
210→			const createdProjects: ProjectRow[] = [];
211→
212→			try {
213→				await client.query("BEGIN");
214→
215→				// Get current max sort_order
216→				const maxResult = await client.query<{ max_order: number | null }>(
217→					`SELECT MAX(sort_order) AS max_order FROM projects WHERE user_id = $1`,
218→					[userId],
219→				);
220→				let sortOrder = (maxResult.rows[0].max_order ?? -1) + 1;
221→
222→				for (const group of groups) {
223→					if (!group.projectName || !Array.isArray(group.sessionIds)) continue;
224→
225→					const validSessionIds = group.sessionIds.filter(id => validIds.has(id));
226→					if (validSessionIds.length === 0) continue;
227→
228→					// Create project
229→					const projResult = await client.query<ProjectRow>(
230→						`INSERT INTO projects (user_id, name, icon, sort_order)
231→						 VALUES ($1, $2, $3, $4)
232→						 RETURNING *`,
233→						[userId, group.projectName, group.icon || null, sortOrder++],
234→					);
235→					const project = projResult.rows[0];
236→					createdProjects.push(project);
237→
238→					// Assign sessions
239→					await client.query(
240→						`UPDATE sessions SET project_id = $1
241→						 WHERE id = ANY($2) AND user_id = $3 AND project_id IS NULL`,
242→						[project.id, validSessionIds, userId],
243→					);
244→				}
245→
246→				await client.query("COMMIT");
247→			} catch (txErr) {
248→				await client.query("ROLLBACK");
249→				throw txErr;
250→			} finally {
251→				client.release();
252→			}
253→
254→			res.json({ success: true, data: { projects: createdProjects } });
255→		} catch (err: any) {
256→			console.error("[projects] AI organize failed:", err);
257→			res.status(500).json({ success: false, error: "Failed to organize sessions" });
258→		}
259→	}));
260→
261→	return router;
262→}
