 1→import type { RequestHandler } from "express";
 2→import { verifyJwt } from "./local-auth.js";
 3→import { consumeSseTicket } from "./sse-tickets.js";
 4→
 5→/**
 6→ * Express middleware that validates JWT from Authorization: Bearer <token> header.
 7→ * Populates req.user with AuthUser.
 8→ * Returns 401 if missing or invalid.
 9→ */
10→export const requireAuth: RequestHandler = (req, res, next) => {
11→	const header = req.headers.authorization;
12→	if (!header?.startsWith("Bearer ")) {
13→		res.status(401).json({ success: false, error: "Missing authorization token" });
14→		return;
15→	}
16→
17→	const token = header.slice(7);
18→	const payload = verifyJwt(token);
19→	if (!payload) {
20→		res.status(401).json({ success: false, error: "Invalid or expired token" });
21→		return;
22→	}
23→
24→	req.user = {
25→		userId: payload.sub,
26→		teamId: payload.teamId,
27→		email: payload.email,
28→		role: payload.role,
29→	};
30→
31→	next();
32→};
33→
34→/**
35→ * Like requireAuth, but also accepts a single-use SSE ticket from ?ticket= query parameter.
36→ * Needed for SSE (EventSource can't set headers).
37→ *
38→ * Checks Authorization header first, then ?ticket= param via the short-lived ticket store.
39→ */
40→export const requireAuthOrToken: RequestHandler = (req, res, next) => {
41→	// Try Authorization header first
42→	const header = req.headers.authorization;
43→	if (header?.startsWith("Bearer ")) {
44→		const token = header.slice(7);
45→		const payload = verifyJwt(token);
46→		if (payload) {
47→			req.user = {
48→				userId: payload.sub,
49→				teamId: payload.teamId,
50→				email: payload.email,
51→				role: payload.role,
52→			};
53→			return next();
54→		}
55→	}
56→
57→	// Try single-use SSE ticket
58→	const ticket = req.query.ticket as string | undefined;
59→	if (ticket) {
60→		const user = consumeSseTicket(ticket);
61→		if (user) {
62→			req.user = user as any;
63→			return next();
64→		}
65→	}
66→
67→	res.status(401).json({ success: false, error: "Missing or invalid authorization" });
68→};
